// ValidateLeadData v1.0
const lead = $input.first().json.body;

const errors = [];
const warnings = [];

// Validar nombre
if (!lead.nombre || lead.nombre.trim().length < 2) {
  errors.push('nombre requerido (mínimo 2 caracteres)');
}

// Validar email
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
if (!lead.email || !emailRegex.test(lead.email)) {
  errors.push('email inválido');
}

// Detectar emails genéricos
const genericDomains = ['gmail.com', 'hotmail.com', 'yahoo.com', 'outlook.com'];
if (lead.email && genericDomains.some(d => lead.email.toLowerCase().endsWith(d))) {
  warnings.push('email personal detectado');
}

// Validar origen
const validOrigenes = ['landing', 'referral', 'manual', 'webinar'];
if (lead.origen && !validOrigenes.includes(lead.origen)) {
  warnings.push('origen no reconocido - usando default');
  lead.origen = 'manual';
}

// Si hay errores, rechazar
if (errors.length > 0) {
  return [{
    json: {
      isValid: false,
      errors,
      warnings,
      originalData: lead,
      action: 'reject'
    }
  }];
}

// Limpiar y normalizar
const cleanLead = {
  nombre:   lead.nombre.trim(),
  email:    lead.email.toLowerCase().trim(),
  empresa:  (lead.empresa  || '').trim(),
  telefono: (lead.telefono || '').trim(),
  origen:   lead.origen || 'manual',
  notas:    (lead.notas   || '').trim(),
  receivedAt: new Date().toISOString()
};

return [{
  json: {
    ...cleanLead,
    isValid: true,
    warnings,
    validatedAt: new Date().toISOString()
  }
}];

// CheckDuplicate v1.0
const lead = $input.first().json;
const leadEmail = lead.email;

// Forma correcta de acceder a memoria persistente en n8n
const staticData = $getWorkflowStaticData('global');

// Si no existe el registro de leads, lo inicializamos
if (!staticData.processed_leads) {
  staticData.processed_leads = {};
}

let processedLeads = staticData.processed_leads;

// Limpiar leads de más de 30 días
const cutoff = Date.now() - (30 * 24 * 60 * 60 * 1000);
Object.keys(processedLeads).forEach(email => {
  if (processedLeads[email].timestamp < cutoff) {
    delete processedLeads[email];
  }
});

const isDuplicate = processedLeads.hasOwnProperty(leadEmail);

if (isDuplicate) {
  const existing = processedLeads[leadEmail];
  console.log(`⏭️ Lead duplicado: ${leadEmail}`);
  return [{
    json: {
      ...lead,
      isDuplicate: true,
      firstSeenAt: new Date(existing.timestamp).toISOString(),
      action: 'update_existing'
    }
  }];
}

// Registrar como procesado
processedLeads[leadEmail] = {
  timestamp: Date.now()
};

console.log(`✅ Lead nuevo: ${leadEmail}`);
return [{
  json: {
    ...lead,
    isDuplicate: false,
    action: 'create_new'
  }
}];

// ParseEnrichment v1.1
// Recuperamos el lead original desde CheckDuplicate
// porque Clearbit sobreescribió los datos del pipeline

const bestMatch = $input.first().json;

// Recuperamos los datos originales del lead desde el nodo anterior
const originalLead = $('CheckDuplicate').first().json;

const enrichedLead = {
  // Datos originales del lead
  nombre:      originalLead.nombre   || '',
  email:       originalLead.email    || '',
  empresa:     originalLead.empresa  || '',
  telefono:    originalLead.telefono || '',
  origen:      originalLead.origen   || 'manual',
  notas:       originalLead.notas    || '',
  isValid:     originalLead.isValid,
  warnings:    originalLead.warnings || [],
  isDuplicate: originalLead.isDuplicate,
  action:      originalLead.action,
  receivedAt:  originalLead.receivedAt,

  // Datos enriquecidos por Clearbit
  company:  bestMatch.name   || '',
  domain:   bestMatch.domain || '',
  logo:     bestMatch.logo   || '',

  // Metadata
  enrichmentMethod: 'clearbit_api',
  enrichedAt: new Date().toISOString()
};

return [{ json: enrichedLead }];

// CalculateLeadScore v1.0
// Calcula puntaje 0-100 basado en reglas de negocio

const lead = $input.first().json;

let score = 0;
const breakdown = {};

// 1. Score por origen
const origenScores = {
  'webinar':  30,
  'referral': 25,
  'landing':  20,
  'manual':   10
};
const origenPts = origenScores[lead.origen] || 0;
score += origenPts;
breakdown.origen = origenPts;

// 2. Penalización por email personal
if (lead.warnings && lead.warnings.includes('email personal detectado')) {
  score -= 15;
  breakdown.email_personal = -15;
}

// 3. Bonus por tener dominio de empresa (Clearbit lo encontró)
if (lead.domain && lead.domain.length > 0) {
  score += 20;
  breakdown.domain_found = 20;
}

// 4. Bonus por datos completos
const camposCompletos = [
  lead.empresa,
  lead.telefono,
  lead.domain,
  lead.company
].filter(Boolean).length;

const completenessPts = camposCompletos * 5;
score += completenessPts;
breakdown.completeness = completenessPts;

// Normalizar entre 0 y 100
score = Math.max(0, Math.min(100, score));

// Clasificar el lead
let categoria = 'Cold';
if (score >= 70) categoria = 'Hot';
else if (score >= 40) categoria = 'Warm';

console.log(`📊 Score: ${score} (${categoria})`);

return [{
  json: {
    ...lead,
    score,
    categoria,
    scoreBreakdown: breakdown,
    scoredAt: new Date().toISOString()
  }
}];
